//! Migration examples compile with defaults and plugins disabled, including wasm.
use std::sync::Arc;
use whatsapp_rust::bot::Bot;
use whatsapp_rust::{
    Client, ClientBuilder, DecryptFailureAdmission, DecryptFailureContext, DecryptFailureDecision,
    RetryAdmission, RetryContext, RetryDecision,
};

pub struct Policy;
impl RetryAdmission for Policy {
    fn decide(&self, context: &RetryContext<'_>) -> RetryDecision {
        if context.retry_count <= 2 {
            RetryDecision::Accept
        } else {
            RetryDecision::Drop
        }
    }
}
impl DecryptFailureAdmission for Policy {
    fn decide(&self, context: &DecryptFailureContext<'_>) -> DecryptFailureDecision {
        if context.retry_count <= 2 {
            DecryptFailureDecision::RequestRetry
        } else {
            DecryptFailureDecision::AcknowledgeWithoutRetry
        }
    }
}

pub fn owned() -> ClientBuilder {
    Client::builder()
        .with_retry_admission(Policy)
        .with_decrypt_failure_admission(Policy)
}

pub fn shared(
    retry: Arc<dyn RetryAdmission>,
    decrypt: Arc<dyn DecryptFailureAdmission>,
) -> ClientBuilder {
    Client::builder()
        .with_retry_admission_arc(retry)
        .with_decrypt_failure_admission_arc(decrypt)
}

pub fn bot() {
    let _ = Bot::builder()
        .with_retry_admission(Policy)
        .with_decrypt_failure_admission(Policy);
    let _ = Bot::builder()
        .with_retry_admission_arc(Arc::new(Policy))
        .with_decrypt_failure_admission_arc(Arc::new(Policy));
}

// wasm policies may keep local state without Send/Sync.
#[cfg(target_arch = "wasm32")]
pub struct LocalPolicy(pub std::rc::Rc<std::cell::Cell<usize>>);
#[cfg(target_arch = "wasm32")]
impl DecryptFailureAdmission for LocalPolicy {
    fn decide(&self, _: &DecryptFailureContext<'_>) -> DecryptFailureDecision {
        self.0.set(self.0.get() + 1);
        DecryptFailureDecision::RequestRetry
    }
}

#[cfg(target_arch = "wasm32")]
pub fn local(state: std::rc::Rc<std::cell::Cell<usize>>) -> ClientBuilder {
    Client::builder().with_decrypt_failure_admission(LocalPolicy(state))
}

#[test]
fn migration_builders_accept_owned_and_shared_policies() {
    let _ = owned();
    let _ = shared(Arc::new(Policy), Arc::new(Policy));
    bot();
}

//! Independent consumer: no transport, session, or runtime is constructed.
use std::{future::Future, pin::Pin, sync::Arc};
use whatsapp_rust::bot::MessageContext;
use whatsapp_rust::prelude::MessageBuilderExt;
use whatsapp_rust::wacore::types::message::{MessageInfo, MessageSource};
use whatsapp_rust::{
    Client, EventCreationParams, MessageRef, NewsletterMessage, NewsletterMessageRef,
    NewsletterMessageType, NewsletterMetadata, NewsletterPollVote, NewsletterReactionCount,
    NewsletterState, NewsletterVerification, PinDuration, RevokeType, StanzaId, anyhow,
    async_trait, waproto::whatsapp as proto,
};

#[cfg(not(target_arch = "wasm32"))]
#[async_trait]
pub trait Host: Send + Sync {
    async fn actions(
        &self,
        target: &MessageRef<'_>,
        post: &NewsletterMessageRef<'_>,
    ) -> anyhow::Result<()>;
}

// Browser clients and their futures are local: ?Send alone does not relax
// the trait's supertraits, so retain Send + Sync only for the native host.
#[cfg(target_arch = "wasm32")]
#[async_trait(?Send)]
pub trait Host {
    async fn actions(
        &self,
        target: &MessageRef<'_>,
        post: &NewsletterMessageRef<'_>,
    ) -> anyhow::Result<()>;
}

#[cfg_attr(target_arch = "wasm32", async_trait(?Send))]
#[cfg_attr(not(target_arch = "wasm32"), async_trait)]
impl Host for Client {
    async fn actions(
        &self,
        target: &MessageRef<'_>,
        post: &NewsletterMessageRef<'_>,
    ) -> anyhow::Result<()> {
        self.chat_actions().star_message(target).await?;
        self.chat_actions().unstar_message(target).await?;
        self.chat_actions()
            .delete_message_for_me(target, false, None)
            .await?;
        self.labels()
            .add_message_label("synthetic", target.chat(), target.id())
            .await?;
        self.labels()
            .remove_message_label("synthetic", target.chat(), target.id())
            .await?;
        self.send_reaction(target, "👍").await?;
        self.keep_message(target, true).await?;
        self.pin_message(target, PinDuration::Days7).await?;
        self.unpin_message(target).await?;
        self.revoke_message(target).await?;
        self.comments().send_text(target, "comment").await?;
        self.comments()
            .send_message(target, proto::Message::text("body"))
            .await?;
        let _: StanzaId = self.newsletter().send_reaction(post, "👍").await?;
        let _: StanzaId = self.newsletter().send_poll_vote(post, &[[7; 32]]).await?;
        self.newsletter()
            .edit_message(post, proto::Message::text("edit"))
            .await?;
        self.newsletter().revoke_message(post).await?;
        Ok(())
    }
}

#[cfg(not(target_arch = "wasm32"))]
pub type BoxedAction<'a> = Pin<Box<dyn Future<Output = anyhow::Result<()>> + Send + 'a>>;
#[cfg(target_arch = "wasm32")]
pub type BoxedAction<'a> = Pin<Box<dyn Future<Output = anyhow::Result<()>> + 'a>>;

pub fn boxed<'a>(
    client: &'a Client,
    target: &'a MessageRef<'a>,
    post: &'a NewsletterMessageRef<'a>,
) -> BoxedAction<'a> {
    Box::pin(client.actions(target, post))
}

/// Raw interop remains explicit and shares the canonical implementation.
pub async fn raw(
    client: &Client,
    target: &MessageRef<'_>,
    post: &NewsletterMessageRef<'_>,
) -> anyhow::Result<()> {
    client
        .send_reaction_raw(target.chat(), target.to_raw_key(), "👍")
        .await?;
    client
        .keep_message_raw(target.chat(), target.to_raw_key(), true)
        .await?;
    client
        .pin_message_raw(target.chat(), target.to_raw_key(), PinDuration::Days7)
        .await?;
    client
        .unpin_message_raw(target.chat(), target.to_raw_key())
        .await?;
    client
        .revoke_message_raw(target.chat(), target.id().as_str(), RevokeType::Sender)
        .await?;
    client
        .comments()
        .send_text_raw(target.chat(), target.to_raw_key(), "comment")
        .await?;
    client
        .comments()
        .send_message_raw(
            target.chat(),
            target.to_raw_key(),
            proto::Message::text("body"),
        )
        .await?;
    let _: StanzaId = client
        .newsletter()
        .send_reaction_raw(post.chat(), post.require_server_id()?.get(), "👍")
        .await?;
    let _: StanzaId = client
        .newsletter()
        .send_poll_vote_raw(post.chat(), post.require_server_id()?.get(), &[[7; 32]])
        .await?;
    client
        .newsletter()
        .edit_message_raw(
            post.chat(),
            post.require_message_id()?.as_str(),
            proto::Message::text("edit"),
        )
        .await?;
    client
        .newsletter()
        .revoke_message_raw(post.chat(), post.require_message_id()?.as_str())
        .await?;
    Ok(())
}

pub fn mock_info() -> MessageInfo {
    MessageInfo {
        id: "COMMENT".into(),
        source: MessageSource {
            chat: "120363000000000001@g.us".parse().expect("fixture group"),
            sender: whatsapp_rust::Jid::lid("100000000000001"),
            is_group: true,
            ..Default::default()
        },
        ..Default::default()
    }
}

pub fn mock_context(client: Arc<Client>) -> MessageContext {
    MessageContext::builder()
        .client(client)
        .message(Arc::new(proto::Message::text("comment")))
        .info(mock_info())
        .ephemeral_expiration(86400)
        .comment_target(Box::new({
            let mut proto_ = proto::MessageKey::default();
            proto_.id = Some("PARENT".into());
            proto_
        }))
        .build()
}

pub async fn context_actions(ctx: &MessageContext) -> anyhow::Result<()> {
    let target = ctx.message_ref()?;
    ctx.react("👍").await?;
    ctx.revoke_message(&target).await?;
    ctx.revoke_message_raw(target.id().as_str(), RevokeType::Sender)
        .await?;
    let MessageContext {
        message,
        ephemeral_expiration,
        ..
    } = ctx;
    let _ = (message, ephemeral_expiration);
    Ok(())
}

pub fn event_params() -> EventCreationParams {
    EventCreationParams::builder()
        .name("Launch".into())
        .description("Description".into())
        .start_time(1_700_000_000)
        .end_time(1_700_003_600)
        .join_link("https://example.invalid/call".into())
        .location(proto::message::LocationMessage::default())
        .is_scheduled_call(true)
        .extra_guests_allowed(false)
        .build()
}

pub fn mock_newsletter() -> NewsletterMetadata {
    NewsletterMetadata::builder()
        .jid(
            "120363000000000001@newsletter"
                .parse()
                .expect("fixture jid"),
        )
        .name("Channel".into())
        .subscriber_count(0)
        .verification(NewsletterVerification::Unverified)
        .state(NewsletterState::Active)
        .build()
}

pub fn mock_history() -> NewsletterMessage {
    NewsletterMessage::builder()
        .server_id(0)
        .timestamp(1_700_000_000)
        .message_type(NewsletterMessageType::Text)
        .edit(whatsapp_rust::wacore::types::message::EditAttribute::Empty)
        .is_sender(false)
        .is_wamo_sub(false)
        .reactions(vec![
            NewsletterReactionCount::builder()
                .code("👍".into())
                .count(2)
                .build(),
        ])
        .votes(vec![
            NewsletterPollVote::builder()
                .option_hash([7; 32])
                .count(1)
                .build(),
        ])
        .build()
}

pub mod construction;
pub mod removed;

/// Construct a detached range from addressing metadata alone, without a client.
pub fn range_from_metadata(
    info: &MessageInfo,
) -> anyhow::Result<whatsapp_rust::SyncActionMessageRange> {
    Ok(whatsapp_rust::message_range(
        42,
        Some(7),
        std::iter::once((MessageRef::from_info(info)?, 41)),
    ))
}

/// The context/result raw-key accessors remain available for explicit interop.
pub fn retained_key_accessors(ctx: &MessageContext, sent: &whatsapp_rust::SendResult) {
    let _: proto::MessageKey = ctx.message_key();
    let _: proto::MessageKey = sent.message_key();
}

#[cfg(all(test, feature = "contracts"))]
mod tests {
    use super::*;
    use whatsapp_rust::{
        NewsletterAdminInfo, NewsletterAdminProfile, NewsletterFollower, NewsletterMyAddOns,
        NewsletterMyPollVote, NewsletterMyReaction,
    };

    #[test]
    fn message_range_outlives_addressing_metadata() {
        let range = {
            let info = mock_info();
            range_from_metadata(&info).unwrap()
        };
        assert_eq!(range.last_message_timestamp, Some(42));
        assert_eq!(range.last_system_message_timestamp, Some(7));
        assert_eq!(range.messages.len(), 1);
        assert_eq!(range.messages[0].timestamp, Some(41));
        let key = range.messages[0].key.as_option().unwrap();
        assert_eq!(key.id.as_deref(), Some("COMMENT"));
        assert_eq!(key.remote_jid.as_deref(), Some("120363000000000001@g.us"));
        assert_eq!(key.participant.as_deref(), Some("100000000000001@lid"));
        assert_eq!(key.from_me, Some(false));
        assert!(
            whatsapp_rust::message_range(0, None, [])
                .messages
                .is_empty()
        );
    }

    #[test]
    fn host_futures_and_mock_construction_are_supported() {
        fn assert_host<T: Host>() {}
        assert_host::<Client>();
        let _ = (boxed, raw, mock_context, context_actions);
        let info = mock_info();
        let reference = MessageRef::from_info(&info).expect("mock is actionable");
        assert_eq!(reference.id().as_str(), "COMMENT");
        assert_eq!(reference.sender(), Some(&info.source.sender));
        let EventCreationParams {
            name, start_time, ..
        } = event_params();
        assert_eq!(name, "Launch");
        assert_eq!(start_time, Some(1_700_000_000));
        let NewsletterMetadata {
            name, description, ..
        } = mock_newsletter();
        assert_eq!(name, "Channel");
        assert!(description.is_none());
        let profile = NewsletterAdminProfile::builder()
            .name("Admin".into())
            .build();
        let NewsletterAdminProfile { name, .. } = &profile;
        assert_eq!(name, "Admin");
        let admin = NewsletterAdminInfo::builder()
            .admin_profile(profile)
            .build();
        let NewsletterAdminInfo { admin_count, .. } = admin;
        assert_eq!(admin_count, None);
        assert_eq!(NewsletterAdminInfo::default().admin_count, None);
        let follower = NewsletterFollower::builder()
            .jid(whatsapp_rust::Jid::lid("100000000000001"))
            .build();
        let NewsletterFollower { phone_jid, .. } = follower;
        assert_eq!(phone_jid, None);
        let NewsletterMessage {
            reactions, votes, ..
        } = mock_history();
        let NewsletterReactionCount { code, count, .. } = &reactions[0];
        assert_eq!((code.as_str(), *count), ("👍", 2));
        let NewsletterPollVote {
            option_hash, count, ..
        } = &votes[0];
        assert_eq!((*option_hash, *count), ([7; 32], 1));
        let mine = NewsletterMyAddOns::builder()
            .server_id(0)
            .reaction(
                NewsletterMyReaction::builder()
                    .code("👍".into())
                    .timestamp(1)
                    .build(),
            )
            .poll_vote(
                NewsletterMyPollVote::builder()
                    .timestamp(2)
                    .option_hashes(vec![])
                    .build(),
            )
            .build();
        let NewsletterMyAddOns {
            reaction,
            poll_vote,
            ..
        } = mine;
        assert_eq!(reaction.unwrap().timestamp, 1);
        let NewsletterMyPollVote { option_hashes, .. } = poll_vote.unwrap();
        assert!(option_hashes.is_empty());
    }
}

//! Builders and `..` patterns in this crate are positive controls. Struct literals
//! (including update syntax from a valid builder result) are intentionally forbidden.
//! Every newly protected DTO is checked independently, so restoring one literal
//! cannot hide behind another's failure. Nightly verifies error codes as well.
//!
//! ```compile_fail,E0639
//! use whatsapp_rust::bot::MessageContext;
//! fn literal(value: MessageContext) { let _ = MessageContext { ..value }; }
//! ```
//!
//! ```compile_fail,E0639
//! use whatsapp_rust::EventCreationParams;
//! fn literal(value: EventCreationParams) { let _ = EventCreationParams { ..value }; }
//! ```
//!
//! ```compile_fail,E0639
//! use whatsapp_rust::NewsletterMetadata;
//! fn literal(value: NewsletterMetadata) { let _ = NewsletterMetadata { ..value }; }
//! ```
//!
//! ```compile_fail,E0639
//! use whatsapp_rust::NewsletterAdminProfile;
//! fn literal(value: NewsletterAdminProfile) { let _ = NewsletterAdminProfile { ..value }; }
//! ```
//!
//! ```compile_fail,E0639
//! use whatsapp_rust::NewsletterAdminInfo;
//! fn literal(value: NewsletterAdminInfo) { let _ = NewsletterAdminInfo { ..value }; }
//! ```
//!
//! ```compile_fail,E0639
//! use whatsapp_rust::NewsletterFollower;
//! fn literal(value: NewsletterFollower) { let _ = NewsletterFollower { ..value }; }
//! ```
//!
//! ```compile_fail,E0639
//! use whatsapp_rust::NewsletterReactionCount;
//! fn literal(value: NewsletterReactionCount) { let _ = NewsletterReactionCount { ..value }; }
//! ```
//!
//! Already non-exhaustive history/tally outputs now have supported mock builders:
//!
//! ```compile_fail,E0639
//! use whatsapp_rust::NewsletterPollVote;
//! fn literal(value: NewsletterPollVote) { let _ = NewsletterPollVote { ..value }; }
//! ```
//!
//! ```compile_fail,E0639
//! use whatsapp_rust::NewsletterMessage;
//! fn literal(value: NewsletterMessage) { let _ = NewsletterMessage { ..value }; }
//! ```
//!
//! Exhaustive external patterns must add `..`, rather than list today's fields.
//!
//! ```compile_fail,E0638
//! use whatsapp_rust::bot::MessageContext;
//! fn pattern(value: MessageContext) {
//!     let MessageContext { message, info, client, ephemeral_expiration, comment_target } = value;
//! }
//! ```
//!
//! ```compile_fail,E0638
//! use whatsapp_rust::EventCreationParams;
//! fn pattern(value: EventCreationParams) {
//!     let EventCreationParams { name, description, start_time, end_time, join_link, location, is_scheduled_call, extra_guests_allowed } = value;
//! }
//! ```
//!
//! ```compile_fail,E0638
//! use whatsapp_rust::NewsletterMetadata;
//! fn pattern(value: NewsletterMetadata) {
//!     let NewsletterMetadata { jid, name, description, subscriber_count, verification, state, picture_url, preview_url, invite_code, role, creation_time, muted, follower_activity_muted } = value;
//! }
//! ```
//!
//! ```compile_fail,E0638
//! use whatsapp_rust::NewsletterAdminProfile;
//! fn pattern(value: NewsletterAdminProfile) {
//!     let NewsletterAdminProfile { id, name, picture_id, picture_direct_path } = value;
//! }
//! ```
//!
//! ```compile_fail,E0638
//! use whatsapp_rust::NewsletterAdminInfo;
//! fn pattern(value: NewsletterAdminInfo) {
//!     let NewsletterAdminInfo { admin_count, admin_profile, admin_profiles_enabled } = value;
//! }
//! ```
//!
//! ```compile_fail,E0638
//! use whatsapp_rust::NewsletterFollower;
//! fn pattern(value: NewsletterFollower) {
//!     let NewsletterFollower { jid, phone_jid, display_name, username, role, follow_time, admin_profile } = value;
//! }
//! ```
//!
//! ```compile_fail,E0638
//! use whatsapp_rust::NewsletterReactionCount;
//! fn pattern(value: NewsletterReactionCount) {
//!     let NewsletterReactionCount { code, count } = value;
//! }
//! ```
//!
//! There is no valid all-default event; the builder requires a name. Whitespace-only
//! names remain rejected by `Events::create` before any send.
//!
//! ```compile_fail,E0599
//! use whatsapp_rust::EventCreationParams;
//! let _ = EventCreationParams::default();
//! ```
//!
//! ```compile_fail,E0277
//! use whatsapp_rust::EventCreationParams;
//! let _ = EventCreationParams::builder().build();
//! ```

//! Each removed spelling has its own negative control. The same imports and typed
//! arguments compile in `Host::actions`. Nightly rustdoc verifies E0599; stable
//! runs these as compile-fail tests but ignores error-code annotations.
//!
//! Ranges accept typed references; the free raw-key factory is removed from
//! both public export paths. Context and send-result methods remain available.
//!
//! ```compile_fail,E0432
//! use whatsapp_rust::message_key;
//! ```
//!
//! ```compile_fail,E0432
//! use whatsapp_rust::features::message_key;
//! ```
//!
//! ```compile_fail,E0271
//! use whatsapp_rust::{message_range, waproto::whatsapp::MessageKey};
//! let _ = message_range(1, None, vec![(MessageKey::default(), 1)]);
//! ```
//!
//! ```compile_fail,E0599
//! use whatsapp_rust::{Client, MessageRef};
//! async fn old(c: &Client, t: &MessageRef<'_>) { let _ = c.send_reaction_ref(t, "👍").await; }
//! ```
//!
//! ```compile_fail,E0599
//! use whatsapp_rust::{Client, MessageRef};
//! async fn old(c: &Client, t: &MessageRef<'_>) { let _ = c.keep_message_ref(t, true).await; }
//! ```
//!
//! ```compile_fail,E0599
//! use whatsapp_rust::{Client, MessageRef, PinDuration};
//! async fn old(c: &Client, t: &MessageRef<'_>) { let _ = c.pin_message_ref(t, PinDuration::Days7).await; }
//! ```
//!
//! ```compile_fail,E0599
//! use whatsapp_rust::{Client, MessageRef};
//! async fn old(c: &Client, t: &MessageRef<'_>) { let _ = c.unpin_message_ref(t).await; }
//! ```
//!
//! ```compile_fail,E0599
//! use whatsapp_rust::{Client, MessageRef};
//! async fn old(c: &Client, t: &MessageRef<'_>) { let _ = c.revoke_message_ref(t).await; }
//! ```
//!
//! ```compile_fail,E0599
//! use whatsapp_rust::{Client, NewsletterMessageRef};
//! async fn old(c: &Client, t: &NewsletterMessageRef<'_>) { let _ = c.newsletter().send_reaction_ref(t, "👍").await; }
//! ```
//!
//! ```compile_fail,E0599
//! use whatsapp_rust::{Client, NewsletterMessageRef};
//! async fn old(c: &Client, t: &NewsletterMessageRef<'_>) { let _ = c.newsletter().send_poll_vote_ref(t, &[]).await; }
//! ```
//!
//! Old main-name raw arities are not aliases either; use the explicitly named raw
//! methods compiled in `raw` instead.
//!
//! ```compile_fail,E0061
//! use whatsapp_rust::{Client, Jid, waproto::whatsapp::MessageKey};
//! async fn old(c: &Client, chat: &Jid) { let _ = c.send_reaction(chat, MessageKey::default(), "👍").await; }
//! ```
//!
//! ```compile_fail,E0061
//! use whatsapp_rust::{Client, Jid, waproto::whatsapp::MessageKey};
//! async fn old(c: &Client, chat: &Jid) { let _ = c.keep_message(chat, MessageKey::default(), true).await; }
//! ```
//!
//! ```compile_fail,E0061
//! use whatsapp_rust::{Client, Jid, PinDuration, waproto::whatsapp::MessageKey};
//! async fn old(c: &Client, chat: &Jid) { let _ = c.pin_message(chat, MessageKey::default(), PinDuration::Days7).await; }
//! ```
//!
//! ```compile_fail,E0061
//! use whatsapp_rust::{Client, Jid, waproto::whatsapp::MessageKey};
//! async fn old(c: &Client, chat: &Jid) { let _ = c.unpin_message(chat, MessageKey::default()).await; }
//! ```
//!
//! ```compile_fail,E0061
//! use whatsapp_rust::{Client, Jid, RevokeType};
//! async fn old(c: &Client, chat: &Jid) { let _ = c.revoke_message(chat, "CONTENT", RevokeType::Sender).await; }
//! ```
//!
//! ```compile_fail,E0061
//! use whatsapp_rust::bot::MessageContext;
//! use whatsapp_rust::RevokeType;
//! async fn old(c: &MessageContext) { let _ = c.revoke_message("CONTENT", RevokeType::Sender).await; }
//! ```
//!
//! ```compile_fail,E0061
//! use whatsapp_rust::{Client, Jid};
//! async fn old(c: &Client, chat: &Jid) { let _ = c.newsletter().send_reaction(chat, 1, "👍").await; }
//! ```
//!
//! ```compile_fail,E0061
//! use whatsapp_rust::{Client, Jid};
//! async fn old(c: &Client, chat: &Jid) { let _ = c.newsletter().send_poll_vote(chat, 1, &[]).await; }
//! ```
//!
//! ```compile_fail,E0061
//! use whatsapp_rust::{Client, Jid, waproto::whatsapp::MessageKey};
//! async fn old(c: &Client, chat: &Jid) { let _ = c.comments().send_text(chat, MessageKey::default(), "comment").await; }
//! ```
//!
//! ```compile_fail,E0061
//! use whatsapp_rust::{Client, Jid, waproto::whatsapp::{Message, MessageKey}};
//! async fn old(c: &Client, chat: &Jid) { let _ = c.comments().send_message(chat, MessageKey::default(), Message::default()).await; }
//! ```

//! A downstream backend implements only required Signal methods. Default batch
//! methods, cache persistence and error chains are exercised through public APIs.
#![cfg(all(feature = "native", not(target_arch = "wasm32")))]
use std::sync::{
    Arc,
    atomic::{AtomicBool, Ordering},
};
use wacore::{
    libsignal::protocol::{ProtocolAddress, SessionRecord},
    store::{
        InMemoryBackend, SignalStoreCache,
        error::{Result, StoreError},
        traits::SignalStore,
    },
};
use whatsapp_rust::{async_trait, bytes::Bytes};

#[derive(Debug)]
struct BackendFailure;
impl std::fmt::Display for BackendFailure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("synthetic write failure")
    }
}
impl std::error::Error for BackendFailure {}

#[derive(Default)]
struct ExternalSignalStore {
    inner: InMemoryBackend,
    sessions: std::sync::Mutex<std::collections::HashMap<String, Bytes>>,
    fail_writes: AtomicBool,
}
#[async_trait]
impl SignalStore for ExternalSignalStore {
    async fn put_identity(&self, address: &str, key: [u8; 32]) -> Result<()> {
        self.inner.put_identity(address, key).await
    }
    async fn load_identity(&self, address: &str) -> Result<Option<[u8; 32]>> {
        self.inner.load_identity(address).await
    }
    async fn delete_identity(&self, address: &str) -> Result<()> {
        self.inner.delete_identity(address).await
    }
    async fn get_session(&self, address: &str) -> Result<Option<Bytes>> {
        Ok(self.sessions.lock().unwrap().get(address).cloned())
    }
    async fn put_session(&self, address: &str, session: &[u8]) -> Result<()> {
        if self.fail_writes.load(Ordering::SeqCst) && address != "allowed" {
            return Err(StoreError::Database(Box::new(BackendFailure)));
        }
        self.sessions
            .lock()
            .unwrap()
            .insert(address.to_owned(), Bytes::copy_from_slice(session));
        Ok(())
    }
    async fn delete_session(&self, address: &str) -> Result<()> {
        self.sessions.lock().unwrap().remove(address);
        Ok(())
    }
    async fn store_prekey(&self, id: u32, record: &[u8], uploaded: bool) -> Result<()> {
        self.inner.store_prekey(id, record, uploaded).await
    }
    async fn load_prekey(&self, id: u32) -> Result<Option<Bytes>> {
        self.inner.load_prekey(id).await
    }
    async fn mark_prekeys_uploaded(&self, ids: &[u32]) -> Result<()> {
        self.inner.mark_prekeys_uploaded(ids).await
    }
    async fn remove_prekey(&self, id: u32) -> Result<()> {
        self.inner.remove_prekey(id).await
    }
    async fn get_max_prekey_id(&self) -> Result<u32> {
        self.inner.get_max_prekey_id().await
    }
    async fn store_signed_prekey(&self, id: u32, record: &[u8]) -> Result<()> {
        self.inner.store_signed_prekey(id, record).await
    }
    async fn load_signed_prekey(&self, id: u32) -> Result<Option<Vec<u8>>> {
        self.inner.load_signed_prekey(id).await
    }
    async fn load_all_signed_prekeys(&self) -> Result<Vec<(u32, Vec<u8>)>> {
        self.inner.load_all_signed_prekeys().await
    }
    async fn remove_signed_prekey(&self, id: u32) -> Result<()> {
        self.inner.remove_signed_prekey(id).await
    }
    async fn put_sender_key(&self, address: &str, record: &[u8]) -> Result<()> {
        self.inner.put_sender_key(address, record).await
    }
    async fn get_sender_key(&self, address: &str) -> Result<Option<Vec<u8>>> {
        self.inner.get_sender_key(address).await
    }
    async fn delete_sender_key(&self, address: &str) -> Result<()> {
        self.inner.delete_sender_key(address).await
    }
}

#[test]
fn failed_flush_preserves_source_and_can_be_retried_by_the_consumer() {
    futures::executor::block_on(async {
        let store = ExternalSignalStore::default();
        let cache = SignalStoreCache::new();
        let address = ProtocolAddress::new("15550001111", 1.into());
        let record = SessionRecord::new_fresh();
        let expected = record.serialize().unwrap();
        cache.put_session(&address, record).await;
        assert!(store.get_session(address.as_str()).await.unwrap().is_none());
        store.fail_writes.store(true, Ordering::SeqCst);
        let error = cache.flush(&store).await.unwrap_err();
        let typed = error
            .downcast_ref::<StoreError>()
            .expect("typed store error");
        assert!(matches!(typed, StoreError::Database(_)));
        assert!(
            std::error::Error::source(typed)
                .unwrap()
                .is::<BackendFailure>()
        );
        assert!(store.get_session(address.as_str()).await.unwrap().is_none());
        store.fail_writes.store(false, Ordering::SeqCst);
        cache.flush(&store).await.unwrap();
        let persisted = store.get_session(address.as_str()).await.unwrap().unwrap();
        assert_eq!(persisted.as_ref(), expected);
        let cold_cache = SignalStoreCache::new();
        assert!(
            cold_cache
                .peek_session(&address, &store)
                .await
                .unwrap()
                .is_some()
        );
        cache.flush(&store).await.unwrap();
        assert_eq!(
            store.get_session(address.as_str()).await.unwrap().unwrap(),
            persisted
        );
    });
}

#[test]
fn external_backend_defaults_preserve_missing_rows_and_conservative_scan() {
    futures::executor::block_on(async {
        let store = ExternalSignalStore::default();
        let first: Arc<str> = Arc::from("15550001111:1");
        let missing: Arc<str> = Arc::from("15550002222:1");
        store
            .put_sessions_batch(&[(first.clone(), Bytes::from_static(b"opaque"))])
            .await
            .unwrap();
        let rows = store
            .get_sessions_batch(&[missing.clone(), first.clone()])
            .await
            .unwrap();
        assert_eq!(rows, vec![(first.clone(), Bytes::from_static(b"opaque"))]);
        assert!(!store.has_session(&missing).await.unwrap());
        assert!(store.has_signal_state_for_user("unseen").await.unwrap());
        store
            .delete_sessions_batch(std::slice::from_ref(&first))
            .await
            .unwrap();
        store
            .delete_sessions_batch(std::slice::from_ref(&first))
            .await
            .unwrap();
        assert!(!store.has_session(&first).await.unwrap());
    });
}

