#[test]
fn adapter_distinguishes_missing_prekeys_from_malformed_persisted_records() {
    use wacore::libsignal::protocol::{PreKeyStore as _, SignalProtocolError};
    use whatsapp_rust::store::{
        persistence_manager::PersistenceManager, signal_adapter::SignalProtocolStoreAdapter,
    };
    futures::executor::block_on(async {
        let backend = Arc::new(InMemoryBackend::new());
        // An empty protobuf decodes but lacks the required key material.
        backend.store_prekey(41, b"", false).await.unwrap();
        let manager = Arc::new(PersistenceManager::new(backend).await.unwrap());
        let adapter = SignalProtocolStoreAdapter::new(manager, Arc::new(SignalStoreCache::new()));
        let corrupt = adapter
            .pre_key_store
            .get_pre_key(41.into())
            .await
            .err()
            .expect("invalid stored key");
        assert!(matches!(corrupt, SignalProtocolError::BackendError(..)));
        let source = std::error::Error::source(&corrupt).expect("stored record cause");
        assert!(source.is::<SignalProtocolError>());
        let missing = adapter
            .pre_key_store
            .get_pre_key(42.into())
            .await
            .err()
            .expect("missing key");
        assert!(matches!(missing, SignalProtocolError::InvalidPreKeyId));
    });
}

#[test]
fn default_batch_failure_can_leave_a_committed_prefix() {
    futures::executor::block_on(async {
        let store = ExternalSignalStore::default();
        store.fail_writes.store(true, Ordering::SeqCst);
        let rows = ["allowed", "rejected", "unreached"]
            .map(|address| (Arc::<str>::from(address), Bytes::from_static(b"opaque")));
        let error = store.put_sessions_batch(&rows).await.unwrap_err();
        assert!(matches!(error, StoreError::Database(_)));
        assert!(store.has_session("allowed").await.unwrap());
        assert!(!store.has_session("rejected").await.unwrap());
        assert!(!store.has_session("unreached").await.unwrap());
        store.fail_writes.store(false, Ordering::SeqCst);
        store.put_sessions_batch(&rows).await.unwrap();
        assert_eq!(
            store
                .get_sessions_batch(&rows.map(|(address, _)| address))
                .await
                .unwrap()
                .len(),
            3
        );
    });
}

#[test]
fn exhausted_contention_remains_classifiable_by_portable_consumers() {
    let error = StoreError::RetriesExhausted {
        op: "external_write".into(),
        attempts: 6,
        source: Box::new(BackendFailure),
    };
    assert!(error.is_database_busy_or_locked());
    match error {
        StoreError::RetriesExhausted { op, attempts, .. } => {
            assert_eq!(op, "external_write");
            assert_eq!(attempts, 6);
        }
        _ => panic!("exhaustion classification changed"),
    }
}

#[test]
fn typed_permanent_errors_are_not_contention() {
    for error in [
        StoreError::Validation("busy worker count is invalid".into()),
        StoreError::InvalidConfig("locked mode requires a key".into()),
        StoreError::Io(std::io::Error::new(
            std::io::ErrorKind::PermissionDenied,
            "database is locked by policy",
        )),
    ] {
        assert!(!error.is_database_busy_or_locked(), "{error:?}");
    }
}

#[test]
fn exhausted_contention_preserves_the_backend_cause() {
    let error = StoreError::RetriesExhausted {
        op: "external_write".into(),
        attempts: 6,
        source: Box::new(BackendFailure),
    };
    let cause = std::error::Error::source(&error).expect("exhaustion lost its backend cause");
    assert!(cause.is::<BackendFailure>());
    assert!(!error.to_string().contains("synthetic write failure"));
}

#[derive(Debug)]
struct OpaqueContext(StoreError);
impl std::fmt::Display for OpaqueContext {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("opaque busy context")
    }
}
impl std::error::Error for OpaqueContext {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.0)
    }
}

#[test]
fn typed_causes_override_opaque_context_messages() {
    let permanent = StoreError::Connection(Box::new(OpaqueContext(StoreError::Validation(
        "invalid worker count".into(),
    ))));
    assert!(!permanent.is_database_busy_or_locked());
    let contention = StoreError::Database(Box::new(StoreError::RetriesExhausted {
        op: "save".into(),
        attempts: 3,
        source: Box::new(BackendFailure),
    }));
    assert!(contention.is_database_busy_or_locked());
}

#[test]
fn opaque_database_causes_keep_the_legacy_text_fallback() {
    for message in ["database is LOCKED", "SQLITE_BUSY: write contention"] {
        for error in [
            StoreError::Database(Box::new(std::io::Error::other(message))),
            StoreError::Connection(Box::new(std::io::Error::other(message))),
        ] {
            assert!(error.is_database_busy_or_locked());
        }
    }
    let permanent = StoreError::Database(Box::new(BackendFailure));
    assert!(!permanent.is_database_busy_or_locked());
    let nested = StoreError::Connection(Box::new(OpaqueContext(StoreError::Database(Box::new(
        BackendFailure,
    )))));
    assert!(nested.is_database_busy_or_locked());
    // Opaque messages cannot distinguish contention from unrelated wording.
    let ambiguous = StoreError::Database(Box::new(std::io::Error::other(
        "busy worker count is invalid",
    )));
    assert!(ambiguous.is_database_busy_or_locked());
}

// Native filesystem fixtures and Tokio test runtime; the separate wasm timer
// harness exercises the portable retry path without pretending to run SQLite VFS.
#![cfg(not(target_family = "wasm"))]

use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};

use diesel::prelude::*;
use wacore::store::error::StoreError;
use wacore::store::traits::{Backend, DeviceStore, ProtocolStore, SignalStore};
use whatsapp_rust_sqlite_storage::{
    CommitBarrierHook, SqliteDatabase, SqliteDatabaseConfig, SqliteStore, Synchronous,
};

// Each destructive test owns a new database and its sidecars. No real accounts.
struct Fixture(std::path::PathBuf);
impl Fixture {
    fn new() -> Self {
        static NEXT: AtomicUsize = AtomicUsize::new(0);
        Self(std::env::temp_dir().join(format!(
            "wa_database_api_{}_{}.db",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        )))
    }
    fn url(&self) -> String {
        self.0.to_string_lossy().into_owned()
    }
}
impl Drop for Fixture {
    fn drop(&mut self) {
        for suffix in ["", "-wal", "-shm"] {
            let mut path = self.0.clone().into_os_string();
            path.push(suffix);
            let _ = std::fs::remove_file(path);
        }
    }
}

fn db_err(e: diesel::result::Error) -> StoreError {
    StoreError::Database(Box::new(e))
}

#[derive(QueryableByName)]
struct Settings {
    #[diesel(sql_type = diesel::sql_types::BigInt)]
    cache_size: i64,
    #[diesel(sql_type = diesel::sql_types::BigInt)]
    synchronous: i64,
    #[diesel(sql_type = diesel::sql_types::BigInt)]
    busy_timeout: i64,
}

async fn settings(db: &SqliteDatabase) -> Settings {
    db.shared()
        .read(|conn| {
            diesel::sql_query("SELECT c.cache_size, s.synchronous, b.timeout AS busy_timeout FROM pragma_cache_size() c, pragma_synchronous() s, pragma_busy_timeout() b")
                .get_result(conn)
                .map_err(db_err)
        })
        .await
        .unwrap()
}

#[tokio::test]
async fn single_account_defaults_and_custom_configuration() {
    let fixture = Fixture::new();
    let store = SqliteStore::open(&fixture.url()).await.unwrap();
    assert_eq!(store.device_id(), 1);
    assert!(!store.exists().await.unwrap());
    assert_eq!(store.create().await.unwrap(), 1);
    assert!(store.load().await.unwrap().is_some());
    let defaults = SqliteDatabaseConfig::default();
    assert_eq!(defaults.pool_size, 1);
    assert_eq!(defaults.read_pool_size, 1);
    assert_eq!(defaults.cache_size_kib, 512);
    let actual = settings(&store.database()).await;
    assert_eq!(actual.cache_size, -512);
    assert_eq!(actual.synchronous, 1);
    assert_eq!(actual.busy_timeout, 30_000);

    let fixture = Fixture::new();
    let custom = SqliteDatabaseConfig {
        cache_size_kib: 128,
        synchronous: Synchronous::Full,
        busy_timeout: std::time::Duration::from_millis(75),
        ..Default::default()
    };
    let store = SqliteDatabase::open(&fixture.url(), custom)
        .await
        .unwrap()
        .store(1);
    let actual = settings(&store.database()).await;
    assert_eq!(actual.cache_size, -128);
    assert_eq!(actual.synchronous, 2);
    assert_eq!(actual.busy_timeout, 75);
}

#[tokio::test]
async fn shared_accounts_and_selected_administration() {
    let fixture = Fixture::new();
    let db = SqliteDatabase::open(&fixture.url(), Default::default())
        .await
        .unwrap();
    assert!(db.list_devices().await.unwrap().is_empty());
    let a = db.provision_device(1).await.unwrap();
    let b = db.create_device().await.unwrap();
    let b_id = b.device_id();
    assert_ne!(a.device_id(), b_id);
    // Already provisioned is an error, never an implicit destructive reset.
    assert!(db.provision_device(1).await.is_err());
    assert_eq!(
        db.list_devices()
            .await
            .unwrap()
            .iter()
            .map(|d| d.id)
            .collect::<Vec<_>>(),
        vec![1, b_id]
    );

    for (store, bytes) in [(&a, b"first".as_slice()), (&b, b"second".as_slice())] {
        store.put_session("15550000001.1", bytes).await.unwrap();
        store
            .put_identity("15550000001.1", [store.device_id() as u8; 32])
            .await
            .unwrap();
        store
            .put_group_metadata("12000000001@g.us", bytes)
            .await
            .unwrap();
    }
    let reopened = db.store(b_id);
    assert_eq!(
        reopened
            .get_session("15550000001.1")
            .await
            .unwrap()
            .unwrap(),
        b"second".as_slice()
    );
    assert_eq!(
        a.get_session("15550000001.1").await.unwrap().unwrap(),
        b"first".as_slice()
    );
    assert_ne!(
        a.load_identity("15550000001.1").await.unwrap(),
        b.load_identity("15550000001.1").await.unwrap()
    );
    let old_identity = b.load().await.unwrap().unwrap().identity_key.public_key;
    let reset = db.reset_device(b_id).await.unwrap();
    assert_eq!(reset.device_id(), b_id);
    assert_ne!(
        reset.load().await.unwrap().unwrap().identity_key.public_key,
        old_identity
    );
    assert!(reset.get_session("15550000001.1").await.unwrap().is_none());
    assert!(
        reset
            .get_group_metadata("12000000001@g.us")
            .await
            .unwrap()
            .is_none()
    );
    assert!(
        reset
            .load_identity("15550000001.1")
            .await
            .unwrap()
            .is_none()
    );
    assert_eq!(
        a.get_group_metadata("12000000001@g.us")
            .await
            .unwrap()
            .unwrap(),
        b"first"
    );
    // Existing handles still address the same id after reset (not revoked).
    assert!(b.exists().await.unwrap());
    db.remove_device(b_id).await.unwrap();
    assert!(!b.exists().await.unwrap());
    assert!(a.exists().await.unwrap());
    assert!(
        matches!(db.reset_device(b_id).await, Err(StoreError::DeviceNotFound(id)) if id == b_id)
    );
    assert!(
        matches!(db.remove_device(b_id).await, Err(StoreError::DeviceNotFound(id)) if id == b_id)
    );
    let next = db.create_device().await.unwrap();
    assert!(next.device_id() > b_id);
    assert_eq!(db.list_devices().await.unwrap().len(), 2);
}

#[tokio::test]
async fn memory_uri_and_scope_lifetime() {
    let fixture = Fixture::new();
    let uri = format!("file:{}?mode=memory&cache=shared", fixture.url());
    let db = SqliteDatabase::open(&uri, Default::default())
        .await
